// a sine wave, straight into the speakers
SinOsc osc => dac;
440 => osc.freq;
2::second => now;

0 => int beat;

while( beat < 4 )
{
    <<< "beat", beat, "at", now/second, "sec" >>>;
    0.5::second => now;
    beat++;
}

